#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    cin >> n;
    vector<pair<long long, long long>> iv(n);
    for (auto& [s, e] : iv) cin >> s >> e;
    sort(iv.begin(), iv.end());
    vector<pair<long long, long long>> merged = {iv[0]};
    for (int i = 1; i < n; i++) {
        if (iv[i].first <= merged.back().second)
            merged.back().second = max(merged.back().second, iv[i].second);
        else
            merged.push_back(iv[i]);
    }
    for (auto& [s, e] : merged) cout << s << " " << e << "\n";
    return 0;
}

