#include <bits/stdc++.h>
using namespace std;

long long sortCount(vector<long long>& a, int lo, int hi) {  // sorts a[lo, hi)
    if (hi - lo <= 1) return 0;
    int mid = (lo + hi) / 2;
    long long count = sortCount(a, lo, mid) + sortCount(a, mid, hi);
    vector<long long> merged;
    int i = lo, j = mid;
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) merged.push_back(a[i++]);
        else {
            merged.push_back(a[j++]);
            count += mid - i;  // a[j] is smaller than every remaining left element
        }
    }
    while (i < mid) merged.push_back(a[i++]);
    while (j < hi) merged.push_back(a[j++]);
    copy(merged.begin(), merged.end(), a.begin() + lo);
    return count;
}

int main() {
    int n;
    cin >> n;
    vector<long long> a(n);
    for (auto& x : a) cin >> x;
    cout << sortCount(a, 0, n) << "\n";
    return 0;
}

